def dict_diff(dicts):
    """
    Subset dictionaries to keys which map to multiple values
    """
    diff = {}
    for key, value in dicts[0].items():
        if all(value == v for v in (d.get(key) for d in dicts[1:])):
            diff[key] = value
    return diff

